import Foundation

private typealias E = EvidenceSeed

/// Alternate tellings, batch N: the same cases, played out another way.
extension StoryVariants {
    static let variantsN: [CaseTemplate] = [motorcycleChaseV1, dopeHouseTrailerV1, parkingDeckRobberyV1, nursingAideNeglectV1, passwordResetV1, dmvCounterV1, gasCanSiphonV1, photoExtortionV1, schoolPostV1, minivanChildDeathV1, cocaineBagStopV1, sweepstakesParlorV1, unlockedGunToddlerV1, employeeIdentityTheftV1, lotteryWinnerV1, keyedCarLotV1, fuelCardMisuseV1, dogfightingRingV1, parkingLotSleeperV1, grandparentHouseV1, birthdayPartyV1, babysitterInjuryV1, exPostingCampaignV1, cityStranglerV1, tipJarV1, churchTreasurerSkimV1, erScuffleV1, pruittMillRoadV1, sharedApartmentV1, noteBanditV1, stalkerCoworkerV1, roommateCreditCardV1, wrongApartmentV1]

    static let motorcycleChaseV1 = SmallCases.make(
        key: "story.motorcycleChase",
        category: .traffic,
        headlines: ["Sport Bike Outruns Patrol Car on the Bypass at Dawn", "Plate Reader Hit Leads Troopers to Bike Owner"],
        law: "fleeing",
        threshold: 5,
        spec: "Operated a motorcycle on a four-lane bypass while fleeing a law enforcement officer, with speed more than 15 mph over the limit and reckless driving.",
        ages: 21...32,
        victim: false,
        summary: "At 5:50 a.m. on {DATE}, a deputy's radar read 118 mph on the bypass for a yellow sport bike. The rider ignored the blue lights, cut across the shoulder, and vanished onto a farm road. A plate reader on the overpass caught the tag, registered to {D}. The rider wore a tinted full-face helmet. {DL} says {D.he} had lent the bike to a cousin that week and was asleep at home.",
        state: [E(.video, 3, "Plate Reader Photo", "The tag is clear as the yellow bike passes under the overpass. The rider is a blur in a dark helmet and a gray jacket."), E(.document, 2, "Title and Insurance", "The bike is titled and insured to {DL}, with no transfer on file."), E(.digital, 2, "Group Ride Post", "Ten days earlier, {DL}'s account posted a clip of the same bike on the bypass with the caption \"empty road, full throttle.\"")],
        defense: [E(.statement, 2, "Lent to a Cousin", "{DL} says a cousin borrowed the bike for the week and kept the key."), E(.document, 1, "Phone Location", "{DL}'s phone sat at {D.his} apartment all night.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did your radar show that morning?", "\"One-eighteen in a fifty-five, a yellow sport bike coming up behind me on the bypass at 5:50 in the morning.\""), .direct("What did the rider do when you lit up?", "\"Dropped a gear, passed two trucks on the shoulder, and took the farm road with no lights on. I lost sight of the bike within seconds.\""), .direct("How did you identify the owner?", "\"A plate reader on the overpass caught the tag clearly. The registration came back to {D}, and the title and insurance match.\""), .direct("What does the plate reader photo show of the rider?", "\"A blur. The rider wore a tinted full-face helmet and a gray jacket, and no feature of the face or hair can be seen.\""), .direct("What did you find in a social media post?", "\"Ten days earlier, {D.his} account posted a clip of the same yellow bike on the bypass, captioned 'empty road, full throttle.'\""), .direct("Did you search the farm road afterward?", "\"Yes, for about an hour with another unit. We found tire marks on the gravel and no bike.\""), .cross("Could you see the rider's face?", "\"No. The visor was tinted, and the helmet covered everything. I could not tell you anything about the person.\""), .cross("Could the rider have been a different build from {D}?", "\"Possibly. I saw a figure crouched low at speed, and I cannot say height or weight with any confidence.\""), .cross("Is the bike registered to the defendant?", "\"Yes, titled and insured to {D.him}, with no transfer on file. That tells me who owns it, not who rode it.\""), .cross("Did you speak to the defendant?", "\"Yes, later that morning. {D.He} said the bike had been lent to a cousin and that {D.he} was asleep at home.\""), .cross("Did you check the cousin?", "\"We attempted to. The cousin has been hard to reach, and the phone number we had no longer works.\"")],
        defenseRole: "Former roommate of {DL}'s cousin",
        defenseExam: [.direct("How do you know the cousin?", "\"I used to share an apartment with {D}'s cousin. We lived together for about a year before I moved out.\""), .direct("Did you see {D} give up the bike?", "\"I saw a set of keys change hands in a parking lot that Monday. I was nearby and recognized both of them.\""), .direct("What did the keys belong to?", "\"I assumed the bike. {DF} handed them over and said something about having it back by the weekend.\""), .direct("Did the cousin ride sport bikes?", "\"Often. The cousin liked fast bikes and talked about riding the bypass early in the morning.\""), .direct("How did the defendant seem when handing over the keys?", "\"Relaxed. It looked like a routine favor between relatives, nothing hurried or secretive.\""), .direct("How was your relationship with the cousin?", "\"Friendly until I moved out. We drifted apart, and I have not heard from the cousin in a while.\""), .cross("Do you know the cousin's phone number?", "\"The number changed. The one I had stopped working, and I do not have a new one.\""), .cross("Did you see the defendant on the morning of the chase?", "\"No. I was not with {D.him} that morning, and I cannot say where {D.he} was.\""), .cross("Did the cousin say the bike would be ridden fast?", "\"Not in those words. The cousin liked speed, and that is all I can say.\""), .cross("Are you sure what the keys opened?", "\"No. I did not see a bike in the lot. I assumed from the conversation.\""), .cross("Are you friends with the defendant?", "\"We know each other through the cousin. I would not call us close.\"")],
        theory: ("The bike belongs to {D}, who rode it away from a deputy.", "The bike was lent out, and the plate says nothing about who rode it."),
        allocution: "\"I should have kept better track of who had my bike. I'm sorry.\"",
        truths: ("The cousin told a friend {DL} rode the bike back to the garage that morning with the engine still hot.", "The cousin later bought a matching gray jacket and has a prior fleeing charge in another county."),
        defendant: [.direct("Were you on the bypass that morning?", "\"No. I was asleep at home. I did not ride the bike that day, and I did not get up until after sunrise.\""), .direct("Who had the bike?", "\"My cousin, since Monday. I handed over the keys in a parking lot, and I expected it back by the weekend.\""), .direct("Why did you post the clip?", "\"That was a month old. I post a lot of ride clips, and I did not think about how it would look.\""), .direct("Why was there no paperwork for the loan?", "\"We are family. I did not think to write anything down, and neither did my cousin.\""), .direct("Where is your cousin now?", "\"I do not know. The number changed, and I have not been able to reach my cousin since the chase.\""), .direct("What do you want the court to know?", "\"I did not run from any deputy. I lent a bike to a relative, and I am sorry I trusted the wrong person.\""), .cross("The bike is titled to you, isn't it?", "\"Yes. It is my bike, and I lent it. I did not ride it that morning.\""), .cross("You posted a clip captioned 'empty road, full throttle' on that same bypass, didn't you?", "\"Yes, a month earlier. I ride fast sometimes, and I am not proud of that.\""), .cross("You cannot produce your cousin, can you?", "\"No. I wish I could. I have tried calling, and the number is dead.\""), .cross("No one saw you asleep at 5:50, did they?", "\"No. I lived alone at that time. I was in bed.\""), .cross("A rider in a gray jacket and dark helmet, and you own both, don't you?", "\"I own a gray jacket and a dark helmet, like many riders do.\"")],
        openings: ("At 5:50 a.m., a deputy's radar read 118 miles an hour on the bypass for a yellow sport bike that ignored the blue lights and vanished onto a farm road. A plate reader tied the tag to {D}, and ten days earlier {D} posted a clip of the same bike on the same road.", "{D} lent the bike to a cousin that week and was asleep at home. A tag on an overpass photo proves who owns the bike, and no one has shown who held the handlebars."),
        closings: ("A bike titled to {D}, a tag on camera, a post bragging about full throttle on that road, and a cousin no one can find. The owner and the rider are the same person.", "A tinted helmet, a rider no one could see, and a cousin who borrowed the keys. Ownership is not riding, and the State has not shown who was on that bike."),
        timeline: [(-10, "A clip of the bike on the bypass is posted."), (-3, "{DL} hands over the keys, {D.he} says."), (0, "5:50 a.m.: the radar and the chase."), (2, "Plate reader hit comes back to {DL}.")],
        identified: "A plate reader on an overpass.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let dopeHouseTrailerV1 = SmallCases.make(
        key: "story.dopeHouseTrailer",
        category: .drugs,
        headlines: ["Doorbell Camera Shows Nonstop Visitors at Lot 12", "Warrant at Mobile Home Turns Up Pills in a Boot"],
        law: "maintainingDwelling",
        threshold: 6,
        spec: "Knowingly kept and maintained a dwelling used for keeping and selling controlled substances, on {DATE}.",
        ages: 24...58,
        victim: false,
        summary: "A neighbor's doorbell camera showed a steady line of short visits to {D}'s mobile home through the spring. On {DATE}, deputies executed a warrant and found 35 hydrocodone pills in a work boot, a pill crusher, a roll of small baggies, and $860 in a coffee can. {DL} says a houseguest slept on the couch and the boot and baggies were the guest's, not {D.his}.",
        state: [E(.physical, 3, "Boot and Baggies", "35 hydrocodone pills in a work boot, a crusher, and small baggies in a hall closet.", .search), E(.video, 3, "Doorbell Footage", "Sixty-one visits of under three minutes in thirty days, mostly after dark."), E(.document, 1, "Lease", "The lot lease and electric account are in {D}'s name.")],
        defense: [E(.statement, 2, "Houseguest", "{DL} says a houseguest had the couch and the closet shelf for two months.")],
        role: "Narcotics investigator",
        exam: [.direct("What did the neighbor's doorbell camera show?", "\"Sixty-one visits to {D}'s mobile home in thirty days, each under three minutes, mostly after dark.\""), .direct("What did deputies find when they executed the warrant?", "\"35 hydrocodone pills in a work boot, a pill crusher, a roll of small baggies, and $860 in a coffee can.\""), .direct("Where in the home were those items?", "\"In a hall closet. The boot, the crusher, and the baggies were together, and the coffee can was on the shelf above.\""), .direct("Whose name is on the lot lease?", "\"{DL}'s, and the electric account is in {DL}'s name too. That ties {DL} to the home, though not to the items.\""), .direct("Was anyone else living in the home?", "\"We found a sleeping bag on the couch. Someone had been staying there, or at least sleeping there.\""), .direct("What does a pattern like sixty-one short visits suggest?", "\"Hand-to-hand sales. People arriving, staying a couple of minutes, and leaving is typical of a small drug operation.\""), .cross("Did anyone see {D} sell anything?", "\"Not on camera. The doorbell camera shows people approaching the door, not any exchange.\""), .cross("Did you identify the visitors?", "\"A few. We did not interview them all, and I do not have statements that they bought anything.\""), .cross("Whose boot was it?", "\"I cannot say. It was a work boot of a common size, and I did not match it to {D.him}.\""), .cross("Were fingerprints taken from the baggies?", "\"Some. They did not give us a clear match to {DL}, and I will not claim they did.\""), .cross("Did the defendant cooperate during the search?", "\"Yes. {DL} stayed calm, answered questions, and told us about the person on the couch.\"")],
        defenseRole: "Park groundskeeper",
        defenseExam: [.direct("What is your job?", "\"I am a groundskeeper for the mobile home park. I mow, patch roads, and handle trash, and I know every lot.\""), .direct("Did you see a guest at Lot 12?", "\"A visitor with a duffel bag, for a few weeks. I saw the visitor coming and going from the trailer.\""), .direct("What did the visitor look like?", "\"I only saw the back and a ball cap. The visitor stayed off by the carport and did not speak to me.\""), .direct("Do you know what the visitor did there?", "\"No. I did not talk with the visitor, and I do not know what went on inside.\""), .direct("How did {D} treat the visitor?", "\"As a friend, I think. I saw them chat on the porch a few times, and {D} seemed to be doing a favor.\""), .direct("Did people visit the trailer a lot?", "\"Yes, some, in the evening. I could not tell you who or why. I stay out of people's business.\""), .cross("Did you see the defendant sell anything?", "\"No. I never saw {DF} hand anything to anyone.\""), .cross("Did you see the visitor sell anything?", "\"No. I did not see anything like that either, and I would not guess.\""), .cross("How often were you at Lot 12?", "\"A couple of times a week. I mowed or hauled trash, and I never went inside.\""), .cross("Did you notice the visitor leave?", "\"One day the duffel bag was gone. I figured the visitor moved on, and I did not think about it.\""), .cross("Do you like the defendant?", "\"I do. {DF} is a good tenant, and I would say so, but I am telling you what I saw.\"")],
        theory: ("{D} ran a trailer where pills were kept and sold.", "{D} let a friend crash and never looked in the closet."),
        allocution: "\"I trusted somebody I shouldn't have. I'm sorry.\"",
        truths: ("{DL}'s phone has texts setting times for people to come by.", "The boot belongs to the guest, who left it behind when he skipped town owing rent."),
        defendant: [.direct("Whose pills were these?", "\"Not mine. I did not own those pills, and I did not put them in that boot.\""), .direct("Who stayed with you?", "\"A friend, on the couch, for a few weeks. The friend left a duffel bag and a pair of boots.\""), .direct("What about all the visitors?", "\"The friend's friends, mostly. They came by to see the friend, and I did not think much of it.\""), .direct("What about the cash in the coffee can?", "\"Utility money. I keep cash for the electric bill and the lot rent in a can on the shelf.\""), .direct("Did you know what was in the boot?", "\"No. I never looked in it, and I did not know there were pills in the closet.\""), .direct("What do you want the jury to know?", "\"I let a friend stay, and I did not ask enough questions. I never sold pills out of my home.\""), .cross("The lease and electric are both in your name, aren't they?", "\"Yes. It is my home, and I take responsibility for who I let in.\""), .cross("The pills, crusher, and baggies were in your hall closet, weren't they?", "\"They were in a closet in my home. I did not know they were there.\""), .cross("Sixty-one visits in thirty days is a lot of traffic for a trailer, isn't it?", "\"It is. I did not count them, and I did not think about how it would look.\""), .cross("You cannot name the friend's friends, can you?", "\"A couple of first names. The friend knows who they are, and I do not.\""), .cross("$860 in a coffee can is a lot for utility money, isn't it?", "\"It was rent and bills for the month. I pay cash, and I keep it where I can reach it.\"")],
        openings: ("A neighbor's doorbell camera showed sixty-one short visits to {D}'s mobile home in thirty days, mostly after dark. Deputies found 35 hydrocodone pills in a work boot, a pill crusher, small baggies, and $860 in a coffee can.", "A houseguest slept on the couch, and the boot and baggies belonged to the guest, not {D}. A busy trailer with a guest and the guest's friends is not a drug house."),
        closings: ("Sixty-one visits of under three minutes, pills in a boot, a crusher, baggies, and cash, all in {D}'s home. Those pieces add up to a dealer's setup.", "A guest on the couch, a boot left in a closet, and no one who ever saw {D} sell. The State has a lease and a closet, and no sale."),
        timeline: [(-30, "A neighbor mounts a doorbell camera."), (-7, "The footage reaches deputies."), (0, "Morning: the warrant is served.")],
        identified: "A neighbor's doorbell camera.",
        aggravating: ["The offense involved sale or delivery"],
        mitigating: ["The defendant has accepted responsibility", "The defendant has a support system in the community"],
        mood: .divided,
        doctrines: ["searchSeizure", "burdenOfProof"])

    static let parkingDeckRobberyV1 = SmallCases.make(
        key: "story.parkingDeckRobbery",
        category: .robbery,
        headlines: ["Phone Tracker Leads to Arrest in Garage Knife Robbery", "Medical Tech Held at Knifepoint Near Stairwell"],
        law: "dangerousRobbery",
        threshold: 7,
        spec: "Took a backpack and its contents from the person of {V}, by the use of a knife, whereby {V}'s life was threatened, at a hospital parking deck on {DATE}.",
        ages: 19...34,
        victim: true,
        summary: "At 6:40 p.m. on {DATE}, {V}, a lab technician leaving a shift, was stopped by the stairwell of a hospital garage by a man with a kitchen knife who took {V.his} backpack. {V}'s phone was inside. Its tracker pinged a house two streets from {D}'s, and deputies found the phone in {D}'s yard. {V} chose {D} from a lineup, but not at once. {DL} says {D.he} bought the phone from a stranger for $40.",
        state: [E(.digital, 3, "Phone Tracker", "{V}'s phone pings at an address two streets from {D}'s within the hour, then in {D}'s yard."), E(.statement, 3, "Lineup Pick", "{V} picked {DL} from a six-person lineup after a long pause, saying, \"I think so. Maybe eighty percent.\""), E(.physical, 2, "Kitchen Knife", "A ten-inch kitchen knife recovered from a drainage ditch behind {D}'s street.", .search)],
        defense: [E(.video, 2, "Stairwell Camera", "A dim image of a man in a dark jacket; the face cannot be made out."), E(.statement, 1, "Bought It", "{DL} says a stranger sold {D.him} the phone for $40.")],
        role: "Robbery detective",
        exam: [.direct("How did you find {D}?", "\"The tracker took us to a street, and the phone was in {D}'s yard under a bucket. {V}'s phone pinged two streets away first.\""), .direct("What happened at the garage?", "\"At 6:40 p.m., {V}, a lab technician leaving a shift, was stopped by the stairwell by someone with a kitchen knife, who took {V}'s backpack.\""), .direct("What was in the backpack?", "\"{V}'s phone, a wallet, and a lunch bag. The phone is what led us to {DL}'s street.\""), .direct("How did the lineup go?", "\"{V} took a minute and picked {DL} from a six person lineup. {V} said, 'I think so. Maybe eighty percent.'\""), .direct("Was the knife recovered?", "\"A ten-inch kitchen knife was found in a drainage ditch behind {D.his} street. We did not lift prints from it.\""), .direct("What did the defendant tell you?", "\"That {D.he} bought the phone from a stranger for $40, and that {D.he} knew it was probably stolen.\""), .cross("Did you see the defendant at the garage?", "\"No. There is no video of that. The garage camera did not cover the stairwell.\""), .cross("Was the knife linked to the defendant?", "\"It was in a ditch. No prints, and no way to say whose it was.\""), .cross("How long did {V} take to pick the defendant?", "\"A long pause, as I said. {V} was not sure at first and said so.\""), .cross("Was {V}'s description of the robber general?", "\"Yes. {V} described height, a dark hooded sweatshirt, and the knife. Many people fit it.\""), .cross("Did anyone see {D} near the garage that night?", "\"No. We have no witness putting {DL} near the garage.\"")],
        defenseRole: "Neighbor",
        defenseExam: [.direct("Where do you live in relation to {D}?", "\"On the next street. I can see part of {D}'s yard from my back deck.\""), .direct("What did you see in the yard that evening?", "\"A person cut through. I saw someone walk quickly across the corner of the yard just after dark.\""), .direct("Did you see anyone drop something?", "\"I saw a shape bend down near the bucket. I could not tell what was in the person's hands.\""), .direct("How did the person look?", "\"Average build, hooded, moving fast. I figured it was someone taking a shortcut to the next block.\""), .direct("Did you see the defendant outside that evening?", "\"I did not. {DF}'s porch light was off, and I did not see anyone come or go from the house.\""), .direct("Do you know the defendant well?", "\"We are neighbors. I have talked to {DF} a few times about fences and parking, nothing more.\""), .cross("Did you see the person's face?", "\"No, only the back. I could not tell you anything about the face.\""), .cross("Could the person have been the defendant?", "\"I cannot say. I do not know {D.his} walk well enough to say yes or no.\""), .cross("How long did you watch?", "\"A few seconds. I did not think anything of it until the deputies came.\""), .cross("Did you call the sheriff?", "\"No. Not until the next day, when I heard about the phone.\""), .cross("What time was this?", "\"I am not certain. After dark and before bedtime.\"")],
        theory: ("{D} robbed a tired worker at knifepoint and hid the phone.", "A stranger sold {D} a stolen phone, and a tired witness guessed."),
        allocution: "\"I shouldn't have taken the phone. I didn't rob anyone.\"",
        truths: ("{DL} had searched how to wipe a phone the same night.", "The same photo of {DL} had been shown to {V} on a detective's screen that afternoon, before the lineup."),
        defendant: [.direct("Where were you at 6:40?", "\"At a friend's, playing cards. We started around six and played until nine.\""), .direct("How did you get the phone?", "\"Someone on a bike sold it to me for forty dollars. It was in a backpack, and I only took the phone.\""), .direct("Why did you hide it under a bucket?", "\"I knew it was probably stolen. I should not have bought it, and I was scared to keep it in the house.\""), .direct("Did you rob {V}?", "\"No. I have never held a knife on anyone, and I have never been near that garage.\""), .direct("Can your friend confirm you were playing cards?", "\"My friend moved away. I have not been able to reach that friend, and I wish I could.\""), .direct("What do you want {V} to know?", "\"I am sorry for what happened to you. I did not do it, and I am sorry I bought a stolen phone.\""), .cross("You had {V}'s phone in your yard, didn't you?", "\"Yes, under a bucket. I bought it for forty dollars, and I did not know whose it was.\""), .cross("You knew the phone was probably stolen, didn't you?", "\"Yes. That is why I hid it. It was a foolish choice.\""), .cross("The knife was in a ditch behind your street, wasn't it?", "\"So I am told. It is not my knife, and I do not know who put it there.\""), .cross("{V} picked you from a lineup, didn't {V.he}?", "\"After a long pause, and not with certainty. {V} may have been mistaken.\""), .cross("You cannot produce the friend who played cards, can you?", "\"No. The friend moved away. I do not have a phone number or an address.\"")],
        openings: ("At 6:40 p.m., {V}, a lab technician leaving a shift, was stopped by a hospital garage stairwell by someone with a kitchen knife who took {V}'s backpack. {V}'s phone pinged a house two streets from {D}'s, and deputies found it in {D}'s yard.", "{D} bought a stolen phone for $40 from a stranger on a bike, which is a different crime. A hesitant lineup pick and a ditch knife with no prints do not make {D} the robber."),
        closings: ("The phone was in {D}'s yard, the lineup picked {D}, and a knife was in the ditch behind {D}'s street. Every thread of this robbery leads to one yard.", "A phone bought from a stranger, a lineup pick at eighty percent, and a knife with no prints. The State has a stolen phone in a yard and not a robber."),
        timeline: [(0, "6:40 p.m.: {V} is robbed by the stairwell."), (0, "7:15 p.m.: the phone pings near {D}'s street."), (1, "Deputies find the phone in {D}'s yard."), (3, "{V} picks {DL} from a lineup.")],
        identified: "A phone tracker and a lineup.",
        aggravating: ["The victim was targeted while leaving work"],
        mitigating: ["The defendant is young"],
        mood: .wantsConviction,
        impact: "I parked in that garage for years. I take the bus now.",
        doctrines: ["eyewitnessID", "burdenOfProof", "lesserIncluded"],
        genders: ["D": .male])

    static let nursingAideNeglectV1 = SmallCases.make(
        key: "story.nursingAideNeglect",
        category: .family,
        headlines: ["Resident Dies After Being Left in Bathroom Overnight", "Call-Light Log Shows Calls Went Unanswered"],
        law: "patientNeglect",
        threshold: 7,
        spec: "Willfully neglected {V}, a resident of a care facility, resulting in death, on {DATE}.",
        ages: 24...60,
        victim: true,
        summary: "{V}, a resident of an assisted-living wing, rang a call light eleven times between midnight and 4 a.m. on {DATE} after falling in the bathroom. The aide on the hall, {D}, silenced the light twice and never went in. {V} was found at 5 a.m. and died of complications days later. {DL} says {D.he} was pulled to another wing by a medical emergency and thought the calls were a leftover alarm.",
        state: [E(.document, 3, "Call-Light Report", "Eleven calls from room 14 between midnight and 4 a.m.; two cleared at the hall panel with {DL}'s code."), E(.document, 3, "Assignment Sheet", "{DL} was the only aide assigned to the hall from 11 p.m. to 7 a.m."), E(.statement, 1, "Morning Aide", "The day aide found {V} cold and wedged beside the toilet.")],
        defense: [E(.document, 1, "Wing Emergency", "A staff log shows a rapid response on the other wing at 1:30 a.m.")],
        role: "Director of nursing",
        exam: [.direct("What did the call-light report show?", "\"Eleven calls from room 14 between midnight and 4 a.m. Two were cleared at the hall panel with {D}'s code.\""), .direct("Who was assigned to that hall?", "\"{DL}, alone, from 11 p.m. to 7 a.m. The assignment sheet lists {DL} as the only aide on that hall.\""), .direct("Who is in room 14?", "\"{V}, a resident of the assisted living wing. {V} fell in the bathroom and rang the call light after the fall.\""), .direct("When was {V} found?", "\"At 5 a.m. by the day aide, cold and wedged beside the toilet. {V} had been on the floor for hours.\""), .direct("What happened to {V}?", "\"{V} died of complications days later. The doctors tied the decline to the fall and the long time without help.\""), .direct("Was there an emergency elsewhere that night?", "\"Yes. A rapid response was called at 1:30 on another wing, and {D.he} was pulled there for a while.\""), .cross("Could {D} have called for help?", "\"There is a radio at the desk. {DL} could have called a supervisor or another aide for backup.\""), .cross("How long was the defendant away from the hall?", "\"About forty minutes at the emergency, according to the other aide. {D.He} returned after two.\""), .cross("Was it normal for call lights to be cleared at the panel?", "\"Aides do clear lights, but only after answering. Clearing without answering is against policy.\""), .cross("Did the defendant report the lights afterward?", "\"No. {D.He} did not write anything about room 14, and said {D.he} thought the calls were a leftover alarm.\""), .cross("Was the facility short on staff?", "\"Yes. One aide for an entire hall at night is thin, and I have raised that concern myself.\"")],
        defenseRole: "Night-shift aide from the other wing",
        defenseExam: [.direct("What do you do at the facility?", "\"I am an aide on the other wing. I work nights, and I was on the same shift as {D}.\""), .direct("Did {D} help with the emergency?", "\"For about forty minutes. A resident on my wing coded, and {D.he} came to help with the chest compressions and the cart.\""), .direct("Was it over by 2?", "\"Around then. The rapid response team took the resident to the hospital, and we cleaned up.\""), .direct("What did the defendant do after the emergency?", "\"Went back toward the hall. I was busy with paperwork, and I did not see where {D.he} went next.\""), .direct("How many aides were on duty?", "\"Two aides for two wings. We could not leave our wings without leaving the others unattended.\""), .direct("Was anyone free to help the defendant?", "\"No. I was tied up with my resident, and the other aide was off sick.\""), .cross("Did the defendant tell you about the call lights?", "\"No. {D.He} did not mention room 14 to me at any time.\""), .cross("Did you hear the call lights from your wing?", "\"No. The panels are separate. I could not hear the hall's lights.\""), .cross("Did you see the defendant at the desk later?", "\"Briefly. I walked by and saw {DF} sitting at the desk, looking drained.\""), .cross("Did you tell a supervisor about the staffing?", "\"I had before. The answer was always that we would manage.\""), .cross("Do you like {D}?", "\"I do. {D.He} is kind to residents, and that is why this has been hard.\"")],
        theory: ("{D} silenced calls and left a fallen resident for hours.", "One aide stretched across two wings by an emergency."),
        allocution: "\"I should have gone in. I will carry that. I'm sorry.\"",
        truths: ("{DL} scrolled {D.his} phone at the desk after 2 a.m. while the light kept ringing.", "The panel code {DL} used was also used by two other aides that night."),
        defendant: [.direct("Why did you clear the light?", "\"I thought it was a stuck alarm. That panel had stuck before, and I cleared it twice without thinking.\""), .direct("Did you check the room?", "\"Not after the emergency. I meant to, and then I got pulled into charting and other calls.\""), .direct("Did you hear the eleven calls?", "\"I heard some of them. I did not count them, and I did not realize they were all from one room.\""), .direct("Who else could have gone?", "\"Nobody was free. The other aide was tied up, and I was the only one on the hall.\""), .direct("What did you do when you learned of {V}'s death?", "\"I was crushed. I thought about those calls every night, and I wished I had walked down the hall.\""), .direct("What would you do differently?", "\"I would check every room, every time, even if I thought it was stuck. I would never clear a light without answering it.\""), .cross("You silenced the light twice, didn't you?", "\"Yes. I thought it was a stuck alarm, and I was wrong.\""), .cross("You never went into room 14, did you?", "\"No. I did not. That is the worst thing I have ever done.\""), .cross("Eleven calls over four hours, and you answered none, didn't you?", "\"I answered some of the other rooms. I did not answer room 14, and I know that.\""), .cross("There is a radio at the desk, isn't there?", "\"Yes. I did not use it. I should have asked for help.\""), .cross("You knew that light meant someone needed help, didn't you?", "\"In general, yes. That night I told myself it was stuck, and I was wrong.\"")],
        openings: ("{V}, a resident of an assisted living wing, rang a call light eleven times between midnight and 4 a.m. after a fall in the bathroom. The aide on the hall, {D}, silenced the light twice and never went in, and {V} died days later.", "{D} was pulled to another wing by a medical emergency and believed the call light was a stuck alarm. One aide on a hall at night is a staffing failure, not neglect on purpose."),
        closings: ("Eleven calls, two cleared from the panel, and a resident on the floor for hours. {D} knew what a call light meant and never opened the door.", "One aide, one emergency, and a panel that had stuck before. The State must prove {D} knew {V} needed help and chose to ignore it."),
        timeline: [(0, "11 p.m.: {DL} takes the hall."), (1, "Just after midnight: {V} falls and the calls begin."), (1, "1:30 a.m.: the emergency on the other wing."), (1, "5 a.m.: {V} is found.")],
        identified: "A call-light report and an assignment sheet.",
        aggravating: ["The victim was particularly vulnerable"],
        mood: .wantsConviction,
        impact: "{V} called for help all night and no one came.")

    static let passwordResetV1 = SmallCases.make(
        key: "story.passwordReset",
        category: .cyber,
        headlines: ["Private Cloud Photos and Notes Leaked After Account Takeover", "Recovery Email Change Traced to Former Partner's Phone Plan"],
        law: "accessingComputers",
        threshold: 8,
        spec: "Willfully and without authorization accessed {V}'s cloud storage and email accounts and changed their recovery information.",
        ages: 24...38,
        victim: true,
        summary: "Two weeks after {V} ended a long relationship with {D}, someone used a reset link to take over {V}'s cloud storage and email on {DATE}, then shared private journal pages and photos with {V}'s relatives. Logs tie the reset requests to a mobile hotspot on {DL}'s phone plan. {DL} says {D.he} lent the phone and hotspot to a visiting friend that weekend.",
        state: [E(.digital, 3, "Account Logs", "Three reset requests and two sign-ins from a mobile hotspot on {DL}'s phone plan, from a laptop.", .search), E(.digital, 2, "Angry Message", "Nine days before, {DL} wrote {V}: \"You'll regret how you left. I know where everything is.\"", .search), E(.document, 2, "Recovery Number", "The new recovery number was a prepaid line activated at a kiosk two days earlier."), E(.video, 1, "Kiosk Camera", "A hooded customer with a face mask buys the prepaid SIM; no face is visible.")],
        defense: [E(.statement, 2, "Visiting Friend", "A friend stayed with {DL} that weekend and used the hotspot."), E(.document, 1, "No SIM", "No SIM card or packaging turned up in {DL}'s home or car.")],
        role: "Digital forensics examiner",
        exam: [.direct("Where did the sign-ins come from?", "\"A mobile hotspot assigned to {D}'s phone plan, both times. The logs show three reset requests and two sign-ins from a laptop.\""), .direct("What was changed on {V}'s account?", "\"The passwords first, then the recovery number, which was moved to a new prepaid line. That locked {V} out.\""), .direct("What happened after the takeover?", "\"Private journal pages and photos were shared with {V}'s relatives. {V} was devastated when they were forwarded.\""), .direct("What was the prepaid line?", "\"A SIM activated at a kiosk two days earlier. A kiosk camera shows a hooded customer in a face mask buying it.\""), .direct("Can you see the face on the kiosk camera?", "\"No. The customer wore a hood and a mask. No face is visible and no feature identifies the buyer.\""), .direct("What message did {V} receive before this?", "\"Nine days earlier, {DL} wrote: 'You'll regret how you left. I know where everything is.' It was sent after the breakup.\""), .cross("Does a hotspot show who held the laptop?", "\"No. Only whose plan. The hotspot connects whoever has the password to the network.\""), .cross("Did you find the SIM?", "\"We did not. We know the line existed and where it was bought, and we do not have the card.\""), .cross("Was the friend's laptop checked?", "\"The friend consented, and we examined it. I will not describe the findings, but we did look.\""), .cross("Could someone else use {D}'s hotspot?", "\"Yes, if they had the password or were nearby. It is not a secure device by itself.\""), .cross("Did the defendant cooperate with your investigation?", "\"Yes. {DL} gave us the phone plan details and told us a friend had used the hotspot.\"")],
        defenseRole: "Weekend houseguest",
        defenseExam: [.direct("How do you know {D}?", "\"We are friends from years back. I visited for a weekend to work and catch up.\""), .direct("Did you use the defendant's hotspot?", "\"Both nights, for work. I needed internet, and {D} gave me the hotspot password.\""), .direct("What did you do on the laptop?", "\"Work tasks, emails, and some browsing. I was on and off the laptop each evening.\""), .direct("Did you know {V}?", "\"I knew the name. {DF} mentioned {V} in passing, and I knew they had a long relationship that ended.\""), .direct("How did the defendant seem that weekend?", "\"Hurt but trying to move on. {D.He} talked about the breakup, and we spent time with other friends.\""), .direct("Where was the defendant when you worked?", "\"In the other room or out. {D.He} was not looking over my shoulder, and I did not need help.\""), .cross("Did you reset any password for {V}?", "\"I will not discuss that beyond what I told the investigators. I know what the logs say.\""), .cross("Did the defendant know what you did on the laptop?", "\"I do not think so. We did not talk about it.\""), .cross("Did you have a reason to target {V}?", "\"I do not want to say more. I knew the name, and that is all.\""), .cross("Did you consent to your laptop being searched?", "\"I did, and I answered the questions I was asked.\""), .cross("Do you owe {D} a favor?", "\"We are friends. That does not change what I am telling you under oath.\"")],
        theory: ("Only {D} had the password, the anger, and the hotspot.", "A shared hotspot and a person who was never searched."),
        allocution: "\"I wrote something cruel. I never touched {V}'s accounts.\"",
        truths: ("The SIM's activation receipt was found in {DL}'s email trash.", "The houseguest sent {V} a message a month later: \"Sorry about what I posted.\""),
        defendant: [.direct("Did you open {V}'s accounts?", "\"No. I did not reset a password, take over an account, or share anything of {V}'s with anyone.\""), .direct("Why did you send {V} that message?", "\"I was hurt and angry. I wrote it in the moment, and I meant that I would be hard to forget, not a threat.\""), .direct("Whose plan and hotspot were used?", "\"Mine. A friend was using it that weekend, for work, and I gave the friend the password.\""), .direct("Who knew your passwords?", "\"Lots of people could guess them. I used simple ones, and friends who visited could have seen me type them.\""), .direct("Did you buy a prepaid line?", "\"No. I have never bought a prepaid SIM. I have my own plan and I never needed another.\""), .direct("What do you want {V} to know?", "\"I am sorry for the message and for the pain. I did not do this to you, and I hope you find out who did.\""), .cross("You wrote 'I know where everything is,' didn't you?", "\"Yes, nine days earlier. It was a stupid thing to write, and I regret that.\""), .cross("The reset requests came from a hotspot on your plan, didn't they?", "\"From my plan. A friend was using the hotspot, so I cannot say who held the laptop.\""), .cross("You are the one with a grievance against {V}, aren't you?", "\"I was hurt by the breakup. That is not the same as hacking an account.\""), .cross("The friend who used your hotspot is not on trial, is the friend?", "\"No. That is why I am here, even though I did not do it.\""), .cross("You never gave the friend's name to {V}, did you?", "\"I gave it to the investigators. I did not contact {V}, because I did not want to make things worse.\"")],
        openings: ("Two weeks after {V} ended a long relationship with {D}, someone used reset links to take over {V}'s cloud storage and email and shared private journal pages and photos with {V}'s relatives. Logs tie the resets to a mobile hotspot on {D}'s plan.", "{D} lent the phone and hotspot to a visiting friend that weekend. A hotspot shows whose plan it was, not whose hands were on the laptop."),
        closings: ("Three resets and two sign-ins from {D}'s hotspot, a prepaid recovery number, and a message saying 'I know where everything is.' Anger and access came together in one person.", "A shared hotspot, a houseguest with a laptop, and a hooded buyer at a kiosk. The State has {D}'s plan and {D}'s anger, not a hand on the keyboard."),
        timeline: [(-14, "{V} ends the relationship."), (-9, "{DL} sends the angry message."), (-2, "A prepaid SIM is bought at a kiosk."), (0, "Reset requests; photos and journal pages go to relatives.")],
        identified: "Hotspot logs tied to {DL}'s phone plan.",
        mood: .divided,
        doctrines: ["burdenOfProof", "expertTestimony"])

    static let dmvCounterV1 = SmallCases.make(
        key: "story.dmvCounter",
        category: .violent,
        headlines: ["License Office Worker Shoved Into File Cabinet After Test Dispute", "Customer Arrested After Pushing Examiner at the Window"],
        law: "assaultGovOfficial",
        threshold: 7,
        spec: "Assaulted {V}, a driver license examiner of the North Carolina Division of Motor Vehicles, while {V.he} was discharging {V.his} official duties, by shoving {V.him} into a file cabinet.",
        ages: 19...60,
        victim: true,
        summary: "On {DATE}, {D} was told at the window that a written test result would not be changed. {DL} slapped the counter, walked around the open end, and shoved {V}, the examiner, into a file cabinet. {V} said {V.he} felt pain in {V.his} ribs for days. A deputy in the lobby arrested {DL} on the spot. {DL} says {D.he} was only trying to reach a form and bumped {V} in the crowded gap.",
        state: [E(.video, 3, "Window Camera", "{DL} rounds the end of the counter and shoves {V} with both hands. {V} hits the cabinet."), E(.statement, 2, "Deputy", "A deputy in the lobby saw the shove and made the arrest."), E(.document, 2, "Test Printout", "{DL}'s written test score was four points under passing.")],
        defense: [E(.statement, 1, "Crowded Gap", "The gap behind the counter is narrow and was crowded with boxes."), E(.document, 1, "Hardship", "{DL} needed a license to drive to a night job that started that week.")],
        role: "License office supervisor",
        exam: [.direct("What happened at the window that day?", "\"{D} slapped the counter, came around the open end, and shoved me hard with both hands. I hit the file cabinet.\""), .direct("What did you tell {D} before that?", "\"That the written test result would not be changed. The printout showed a score four points under passing.\""), .direct("What did the camera show?", "\"It shows {DL} rounding the end of the counter and shoving me with both hands. I stumbled into the cabinet.\""), .direct("What did you feel afterward?", "\"Pain in my ribs. It lasted several days, and I had trouble breathing deeply and lifting things at work.\""), .direct("What did the deputy do?", "\"A deputy in the lobby saw the shove and made the arrest on the spot, before {DL} could leave.\""), .direct("How did you feel at the moment?", "\"Shocked. I have worked at this counter for years, and no one had ever laid hands on me.\""), .cross("Was the defendant the only person near the counter?", "\"No. It was a busy morning, and several customers were in the lobby near the window.\""), .cross("Was the gap at the end of the counter narrow?", "\"It is tight, yes. It is only wide enough for one person to pass.\""), .cross("Was the defendant yelling?", "\"{D.He} was upset. I would not call it threats, but the voice was raised.\""), .cross("Did the defendant say anything about wanting a form?", "\"I do not recall. {D.He} was upset about the score, and I did not hear a request.\""), .cross("Were you injured badly?", "\"Bruised ribs, no breaks. I was off work a couple of days.\"")],
        defenseRole: "Customer waiting at the window",
        defenseExam: [.direct("What were you doing at the window?", "\"Waiting for my turn. I was a few steps from the counter, and I had a good view.\""), .direct("What did you see?", "\"A big argument and then a push. {D} was upset, then went around the end of the counter, and there was contact.\""), .direct("How loud was the argument?", "\"Loud enough that the whole lobby turned. {DF} said the test was wrong and wanted someone to look at it.\""), .direct("How did {V} react?", "\"Stepped back, said the result would not change, and then {V} was pushed into the cabinet.\""), .direct("Did it look like a bump?", "\"I thought it was a shove. Both hands were out, and it looked deliberate to me.\""), .direct("What happened right after?", "\"A deputy was there almost at once. The lobby went quiet, and people moved away.\""), .cross("Did you hear {D} say anything about a form?", "\"Not that I recall. I only heard the argument about the score.\""), .cross("Could the gap have been crowded?", "\"It was tight, with several people near the window. I do not know how close {DF} was to the others.\""), .cross("Could someone lose balance in that space?", "\"Yes, anyone could. I still thought it looked like a shove.\""), .cross("Did you know the defendant before?", "\"No. I had never met {D.him}, and I have no stake in this.\""), .cross("Are you sure about what you saw?", "\"I am sure about what I saw. I cannot say what {D.he} meant.\"")],
        theory: ("{D} shoved a state employee over a test score.", "A crowded gap and an accidental bump."),
        allocution: "\"I lost my temper. I'm sorry to {V}.\"",
        truths: ("{DL} said, \"Next time I'll do it again,\" while being led out.", "{DL} reached for the form and slipped on a wet mat that no one had marked."),
        defendant: [.direct("Did you shove {V}?", "\"No. I lost my footing in the gap and bumped {V}. I did not mean to hit anyone.\""), .direct("Why go around the counter?", "\"To get my form. I wanted to see the test sheet, and the form was on the other side.\""), .direct("You were angry, weren't you?", "\"I was upset about the test. I studied for weeks, and I missed by four points.\""), .direct("Why does the camera show two hands?", "\"I grabbed for balance. I put my hands out and caught {V} instead of the counter.\""), .direct("What did you do after you hit the cabinet?", "\"I froze. I did not know {V} was hurt, and then the deputy was on me.\""), .direct("What do you want {V} to know?", "\"I am deeply sorry. I never meant to hurt you, and I will not do anything like that again.\""), .cross("You slapped the counter before going around it, didn't you?", "\"Yes, out of frustration. I should not have, and it looked aggressive.\""), .cross("You went around the open end of the counter, didn't you?", "\"Yes. It was not for customers. I should have waited.\""), .cross("The camera shows both hands on {V}, doesn't it?", "\"It shows hands on {V}. I was grabbing for balance.\""), .cross("{V} had ribs that hurt for days, didn't {V.he}?", "\"I am sorry to hear it. That is not what I intended.\""), .cross("You were four points under passing, weren't you?", "\"Yes. It was a bitter disappointment, and I let it show.\"")],
        openings: ("{D} was told at a license office window that a written test result would not be changed. {D} slapped the counter, walked around the open end, and shoved {V}, the examiner, into a file cabinet, leaving {V} in pain for days.", "{D} was trying to reach a form in a crowded gap and lost {D.his} footing. A frustrated test taker who bumps someone by accident is not an assailant."),
        closings: ("A slap on the counter, a walk around the end, and two hands on {V}. The camera shows what happened, and a deputy saw it too.", "A tight gap, a crowd, and a stumble from a person upset about a test. The State must prove {D} shoved {V} on purpose, and {D} says it was a slip."),
        timeline: [(0, "Morning: {DL} takes the written test."), (0, "10:15 a.m.: the result is handed back."), (0, "10:20 a.m.: the shove."), (0, "10:22 a.m.: the arrest.")],
        identified: "Window camera and a deputy.",
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let gasCanSiphonV1 = SmallCases.make(
        key: "story.gasCanSiphon",
        category: .property,
        headlines: ["Landscaper's Truck Drained Behind Hardware Store", "Fuel Jugs Found in Trunk After Lot Camera Alert"],
        law: "misdLarceny",
        threshold: 5,
        spec: "Stole about eighteen gallons of diesel valued at $82 from a work truck belonging to {V}, on {DATE}.",
        ages: 20...60,
        victim: true,
        summary: "{V}'s work truck was parked behind a hardware store on {DATE}. A lot camera showed {D} fitting a pump hose to the tank in the evening. When {V} came back, the tank was nearly empty and two jugs were missing. Deputies found two jugs of diesel in {D}'s trunk. {DL} says {D.he} thought the truck was abandoned and that {V} had said before that {D.he} could use leftover fuel.",
        state: [E(.video, 3, "Lot Camera", "{D} runs a hose from the tank into jugs for about twenty minutes."), E(.physical, 2, "Jugs", "Two jugs of diesel in {D}'s trunk, one still wet on the cap.")],
        defense: [E(.statement, 1, "Leftover Fuel", "{DL} says {V} once told {D.him} to take leftovers.")],
        role: "Store manager",
        exam: [.direct("What did the lot camera show?", "\"It shows {D} running a pump hose from the tank of {V}'s truck into jugs for about twenty minutes, in the evening behind my store.\""), .direct("Whose truck was it?", "\"{V}'s work truck. It had a company name on the door, a work tag, and a full tool rack in the bed.\""), .direct("Did anyone have leave to drain it?", "\"Not that I know. Nobody at the store gave permission, and nobody called me to say a driver could take fuel.\""), .direct("Was the truck plainly abandoned?", "\"No. It was parked in the lot as if the owner had stepped away, with tools in the rack and a tag in the window.\""), .direct("What did {V} find on returning?", "\"The tank was nearly empty and two jugs were missing from the bed. {V} called the sheriff right away.\""), .direct("What did deputies find in {D}'s trunk?", "\"Two jugs of diesel, and one was still wet on the cap. That tied the jugs to the fuel taken that night.\""), .cross("Did you see the defendant drain the tank yourself?", "\"No. I watched the video later. I was inside the store and did not see anything in the lot.\""), .cross("Did the defendant try to hide what {D.he} was doing?", "\"No. {D.He} did it in the open, in view of the camera, over twenty minutes, with a car parked nearby.\""), .cross("Did the defendant say the truck looked abandoned?", "\"That is what was reported to me. I can see how a parked truck behind a store could look unattended.\""), .cross("Does the store keep records of vehicles parked behind it?", "\"No. People park there for deliveries, and we do not log every truck.\""), .cross("Did {V} tell anyone the defendant could use the fuel?", "\"I do not know. I never heard {V} say that, and I was not asked.\"")],
        theory: ("{D} drained a work truck.", "A tank {D} thought was abandoned and a past offer."),
        allocution: "\"I took it. I'm sorry.\"",
        truths: ("{DL} bought the pump a day earlier.", "{V} had texted, \"Take what's left in the jugs,\" about a week before."),
        defendant: [.direct("Why were you there?", "\"I needed fuel for a job. I was low on diesel, and I saw a work truck parked behind the store.\""), .direct("Did you think the truck was abandoned?", "\"I did. It had been in the same spot for days, and no one seemed to be around it.\""), .direct("Did you ask first?", "\"Not that day. I should have, and I am embarrassed that I did not even knock on the store door.\""), .direct("What about the pump?", "\"It was in my truck. I keep a pump for filling jugs on job sites, and I used it that evening.\""), .direct("Did {V} say you could use fuel?", "\"Last week, in passing. {V} said I could use leftover fuel, and I took that to mean this truck.\""), .direct("What do you want {V} to know?", "\"I am so sorry. I should have called first, and I will pay for the fuel.\""), .cross("You ran a hose from someone else's tank, didn't you?", "\"Yes. I did, and I thought the truck was abandoned. I was wrong to assume.\""), .cross("The truck had a company name on the door, didn't it?", "\"Yes. I saw it, and I still thought it was left behind. I should have looked harder.\""), .cross("The tool rack was full, wasn't it?", "\"It was. I did not think about that, and I should have, yes.\""), .cross("You took two jugs of diesel, didn't you?", "\"Yes. They were in my trunk when the deputy came, and I told the deputy exactly where they came from.\""), .cross("You did not ask {V} that day, did you?", "\"No. I did not. I relied on something {V} said a week before.\"")],
        openings: ("{V}'s work truck sat behind a hardware store when a lot camera showed {D} fitting a pump hose to the tank for twenty minutes. The tank was nearly empty, and deputies found two jugs of diesel in {D}'s trunk.", "{D} believed the truck was abandoned and that {V} had said leftover fuel was fair game. A mistaken belief, openly acted on in view of a camera, is not theft."),
        closings: ("A work truck with a company name, a pump hose on camera for twenty minutes, and diesel in {D}'s trunk. {D} never asked anyone first.", "An old truck behind a store, a leftover-fuel remark from {V}, and a person acting in the open. The State must prove {D} knew the fuel was not {D}'s to take."),
        timeline: [(-7, "{V} tells {DL} to take leftover jugs, {D.he} says."), (0, "6 p.m.: {V} parks behind the store."), (0, "7:10 p.m.: the hose goes in."), (0, "9 p.m.: {V} finds the tank empty.")],
        identified: "A lot camera.",
        mood: .indifferent,
        genders: ["D": .male])

    static let photoExtortionV1 = SmallCases.make(
        key: "story.photoExtortion",
        category: .whiteCollar,
        headlines: ["Anonymous Email Threatens to Send Private Images to Church Board", "Demand for $4,500 Traced to Prepaid Card"],
        law: "extortion",
        threshold: 7,
        spec: "Threatened {V} with the release of private images to obtain $4,500, on {DATE}.",
        ages: 24...55,
        victim: true,
        summary: "On {DATE}, {V} got an email from a throwaway address demanding $4,500 in gift cards or private images would go to {V}'s church board and family. The gift cards were bought with a prepaid card registered to {D}, a former friend who once helped {V} set up a phone backup. {DL} says {D.he} sold the prepaid card online weeks before.",
        state: [E(.digital, 3, "Email Demand", "'$4,500 in gift cards by Sunday or the board gets everything.'"), E(.document, 3, "Prepaid Card Records", "The card that bought the gift cards was registered to {D}."), E(.digital, 1, "Image Backup", "The images match a cloud backup {D} once helped {V} set up.")],
        defense: [E(.statement, 2, "Sold the Card", "{DL} says {D.he} sold the card in an online listing weeks before.")],
        role: "Victim",
        exam: [.direct("What did the email say?", "\"'$4,500 in gift cards by Sunday or the board gets everything.' It came from a throwaway address I did not recognize.\""), .direct("What was the threat about?", "\"Private images of mine that would go to my church board and my family. I was terrified and ashamed.\""), .direct("Who had access to those images?", "\"One friend who helped me with the backup. That friend set up my phone backup and knew where it was stored.\""), .direct("Did you pay?", "\"I bought the gift cards with my own money, because I panicked. I reported it to the sheriff soon after.\""), .direct("How did investigators trace the gift cards?", "\"The card that bought them was a prepaid card registered to {D}, the friend who helped me with the backup.\""), .direct("What was the effect on you?", "\"I could not sleep, I could not eat, and I dreaded Sunday. I thought my whole life would come apart.\""), .cross("Did you see who sent the email?", "\"No. I only know it came from a throwaway address. I cannot see who typed it.\""), .cross("Had the friend ever threatened you?", "\"Never. We were friendly, and the friend was always kind about the phone.\""), .cross("Could others reach the backup?", "\"Anyone with the password could. I gave the password to the friend once, and I never changed it.\""), .cross("Did you change the password afterward?", "\"Yes, after the demand. I should have done it long before.\""), .cross("Did you tell the friend about the email?", "\"Not at first. I was too scared and embarrassed to tell anyone.\"")],
        theory: ("{D} demanded money to keep images private.", "The card was sold and {D} never sent a thing."),
        allocution: "\"I'm sorry. I put {V} through this.\"",
        truths: ("{DL} messaged a friend, \"Sunday is payday,\" the night before the demand.", "The buyer of the card messaged {DL} to say it arrived the week before."),
        defendant: [.direct("Did you send the email?", "\"No. I did not send the email, and I did not buy the gift cards.\""), .direct("Why was the card registered to you?", "\"I registered it, then sold it. I bought a prepaid card and sold it online a few weeks before.\""), .direct("Where is the sale record?", "\"The listing was deleted after the sale. I did not save a copy, and I wish I had.\""), .direct("Who else could reach the backup?", "\"Anybody with the password. I set it up with {V} years ago, and I never took the password off my own devices.\""), .direct("How did you feel when you learned about the demand?", "\"Sick. I was friends with {V}, and I could not believe anyone would do that.\""), .direct("What do you want {V} to know?", "\"I am sorry this happened. I did not do it, and I hope you find who did.\""), .cross("The card that bought the gift cards was registered to you, wasn't it?", "\"Yes, in my name. I sold it weeks before, and I do not know who used it.\""), .cross("You helped {V} set up the backup, didn't you?", "\"Yes, years ago. I helped as a friend, and I did not look at anything.\""), .cross("You cannot show a record of the sale, can you?", "\"No. The listing was deleted, and I have no copy.\""), .cross("You and {V} had a falling out, didn't you?", "\"We drifted apart. It was not a fight, and I never wished {V} harm.\""), .cross("You never reported the card as sold, did you?", "\"No. I did not think I needed to, and that was a mistake.\"")],
        openings: ("{V} received an email from a throwaway address demanding $4,500 in gift cards or private images would go to {V}'s church board and family. The cards were bought with a prepaid card registered to {D}, a former friend who once helped {V} set up a phone backup.", "{D} sold that prepaid card online weeks earlier and never sent a demand. A card registered in {D}'s name is not proof of who used it."),
        closings: ("A threat to a church board, gift cards bought with {D}'s prepaid card, and images from a backup {D} helped set up. Access, means, and money all lead to {D}.", "A card sold online, a listing deleted, and a backup anyone with the password could open. The State has a name on a card, and no proof {D} sent the email."),
        timeline: [(-30, "{DL} helps {V} set up a cloud backup."), (-14, "{DL} registers the prepaid card."), (0, "The email demand arrives."), (4, "Gift cards are bought with the card.")],
        identified: "Prepaid card records.",
        mood: .wantsConviction,
        genders: ["D": .male])

    static let schoolPostV1 = SmallCases.make(
        key: "story.schoolPost",
        category: .publicOrder,
        headlines: ["Teen's Gunshot Meme About Exams Prompts Lockdown at School", "Joke or Threat? Student Charged After Group Chat Image"],
        law: "massViolenceThreat",
        threshold: 1,
        spec: "Threatened to commit an act of mass violence on educational property.",
        ages: 19...19,
        victim: false,
        summary: "On {DATE}, {D}, a senior, sent a group chat of about 90 classmates an edited image of the school entrance with the text \"nobody needs to be here monday\" and a gunshot sound clip. Parents flooded the office with calls overnight, and on Monday the school locked down for three hours. Deputies found no weapons. {DL} says it was an inside joke about a canceled field trip and that the chat knew it.",
        state: [E(.digital, 3, "Group Chat Image", "The school photo with \"nobody needs to be here monday\" and a gunshot clip."), E(.document, 2, "Lockdown Report", "Three hours of lockdown, eleven deputies, and 61 percent absences Monday."), E(.digital, 2, "Prior Messages", "Weeks earlier, {DL} sent \"I swear I'll blow up this place\" in a different chat.")],
        defense: [E(.document, 3, "Chat Context", "Twenty messages before the image show classmates joking about the canceled field trip."), E(.document, 2, "Character", "No discipline history, band section leader."), E(.statement, 1, "Reaction", "Classmates replied with laughing emoji.")],
        role: "School resource officer",
        exam: [.direct("What did the image say?", "\"'Nobody needs to be here Monday,' laid over a photo of the school entrance, with a gunshot sound clip attached.\""), .direct("Who received it?", "\"About ninety classmates in a group chat. Within hours, screenshots were circulating well beyond that chat.\""), .direct("What was the response?", "\"A lockdown and a lot of frightened parents. They flooded the office with calls overnight.\""), .direct("What did the lockdown report show?", "\"Three hours of lockdown on Monday, eleven deputies at the school, and 61 percent absences that day.\""), .direct("Were there weapons?", "\"No. Deputies searched the building and the grounds and found no weapon and no sign of a plan.\""), .direct("What about the earlier message?", "\"Weeks earlier, {D} wrote 'I swear I'll blow up this place' in a different chat. We learned of that after the image.\""), .cross("Did classmates laugh at the image?", "\"Some did. A few answered with jokes, and others forwarded it with worried notes.\""), .cross("Did anyone report it?", "\"One student did, and that report started everything. I took the report seriously.\""), .cross("Did {D} threaten a specific person?", "\"No. The image named no one and listed no date beyond Monday.\""), .cross("Did you find a plan or a weapon at the defendant's home?", "\"No. We searched with consent and found nothing.\""), .cross("Did the defendant cooperate?", "\"Yes. {D.He} told us it was a joke about a canceled field trip and apologized.\"")],
        defenseRole: "{DL}'s bandmate",
        defenseExam: [.direct("How do you know {D}?", "\"We are in a band together. We practice a few nights a week and play small shows.\""), .direct("What did you think the image meant?", "\"It was about the field trip being canceled. We had all been complaining about it.\""), .direct("Was there an inside joke?", "\"Yes. The class had joked that nobody would show up for school if the trip was canceled.\""), .direct("Why the gunshot sound?", "\"It was a sound clip from a meme we all knew. It was dark humor, but I did not think of it as a threat.\""), .direct("Did anyone report it?", "\"One person did. I heard that the person was worried and did the right thing.\""), .direct("What is the defendant like?", "\"Funny, kind, and a little careless about how jokes land. {D} has never hurt anyone.\""), .cross("Did you take the image as a joke from the start?", "\"Yes. But I know others did not, and I understand why.\""), .cross("Did the defendant tell you about the earlier message?", "\"Not before it came out. {D.He} said it was about a video game.\""), .cross("Did you think it was in good taste?", "\"No. It was a bad joke, and {D.he} should not have sent it.\""), .cross("Did you read the earlier chat?", "\"Not before the investigators did. I do not know the whole context.\""), .cross("Would a stranger have read it differently?", "\"Yes, absolutely. Without the context, it would look frightening.\"")],
        theory: ("{D} sent a threat that shut down a school.", "A dark joke in a group of friends."),
        allocution: "\"It was stupid and I'm sorry.\"",
        truths: ("{DL} had searched for school schedules and cameras the week before.", "The image was copied from a meme that circulated the same week."),
        defendant: [.direct("Why did you send the image?", "\"To get a laugh. The field trip was canceled, and everybody in the chat was complaining about it.\""), .direct("Did you mean harm?", "\"No. I never meant to hurt anyone or scare anyone. I thought the chat knew it was a joke.\""), .direct("What about the earlier message?", "\"A video game. We were playing, I lost, and I wrote something dramatic in a chat about the game.\""), .direct("Why the gunshot?", "\"It was a sound from the meme. I did not think about how it would sound to someone outside the chat.\""), .direct("How did you feel when the lockdown started?", "\"Horrified. I did not know it would spread so far, and I could not undo it.\""), .direct("What do you want the school to know?", "\"I truly am sorry. I frightened people, and I was thoughtless. I would never hurt anyone at school.\""), .cross("You wrote 'nobody needs to be here monday', didn't you?", "\"Yes. I thought everyone would read it as the field trip joke.\""), .cross("You sent a gunshot sound with it, didn't you?", "\"Yes. I know it looks terrible. It was from a meme, and I did not think.\""), .cross("You also wrote 'I swear I'll blow up this place' once, didn't you?", "\"In a game chat, weeks before. I meant the game, and I should not have used those words.\""), .cross("Eleven deputies and three hours of lockdown came from your post, didn't they?", "\"Yes. I am responsible for that, and I apologize.\""), .cross("Parents were terrified overnight, weren't they?", "\"I know. I cannot forget that, and I wish I could take it back.\"")],
        openings: ("{D}, a senior, sent about ninety classmates an edited image of the school entrance reading 'nobody needs to be here monday,' with a gunshot clip. Parents flooded the office, the school locked down for three hours, and weeks earlier {D} wrote 'I swear I'll blow up this place.'", "It was an inside joke about a canceled field trip, and the chat knew it. A thoughtless joke that frightened a community is not a plan to commit violence."),
        closings: ("A school photo, a gunshot, a promise that nobody needs to be here Monday, and an earlier message about blowing up the place. A lockdown, eleven deputies, and 61 percent absences followed.", "A canceled field trip, a meme sound, and a game chat. The State must prove {D} meant to threaten, and {D}'s friends all read it as a joke."),
        timeline: [(-7, "The field trip is canceled."), (0, "Evening: the image is sent."), (0, "9 p.m.: a classmate reports it."), (1, "Monday: lockdown.")],
        identified: "A classmate's report.",
        mood: .divided,
        doctrines: ["burdenOfProof"])

    static let minivanChildDeathV1 = SmallCases.make(
        key: "story.minivanChildDeath",
        category: .traffic,
        headlines: ["Child Killed When Pickup Hits Family Van Leaving Soccer Field", "Blood Test Shows Driver Impaired After Fatal Crash"],
        law: "felonyDBV",
        threshold: 8,
        spec: "Unintentionally caused the death of {V} while driving impaired, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A pickup driven by {D} crossed the center line on a two-lane road on {DATE} at dusk and hit a family van, killing {V}, a seven-year-old in the back seat. A blood draw at the hospital measured .12. {DL} says a deer ran into the road and that the drinks were hours earlier.",
        state: [E(.forensic, 3, "Blood Result", "A hospital blood draw taken two hours after the crash measured .12."), E(.physical, 3, "Scene Marks", "Tire marks cross the center line a hundred feet before the van, with no braking."), E(.statement, 2, "Van Driver", "The van driver saw the pickup drift across and could not swerve.")],
        defense: [E(.statement, 2, "Deer", "{DL} says a deer crossed in front of the pickup and caused the swerve."), E(.document, 1, "Receipt", "A restaurant receipt shows two drinks at 2 p.m.")],
        role: "Highway Patrol trooper",
        exam: [.direct("What did the scene show?", "\"The pickup crossed the center line and hit the family van head-on at dusk on a two-lane road.\""), .direct("What did the marks show?", "\"Tire marks crossing the center line about a hundred feet before the van, with no sign of braking.\""), .direct("Who was killed?", "\"{V}, a seven-year-old in the back seat of the van. The child died at the scene.\""), .direct("What was the blood result?", "\"A .12 from a hospital draw taken about two hours after the crash.\""), .direct("What did the van's driver tell you?", "\"The pickup drifted across the line and the driver could not swerve in time. There was no time to avoid it.\""), .direct("Was there a deer?", "\"We found hair on the shoulder, yes. A deer may have been in the area, but we found no body.\""), .cross("Could the level have been higher at the time of the crash?", "\"It would have been. Alcohol is eliminated over time, so a draw two hours later is lower than at the crash.\""), .cross("Could a deer have caused a driver to swerve?", "\"It could. Deer cause crashes like this, and I have seen many on that road.\""), .cross("Did {D} stay at the scene?", "\"Yes. {D} stayed, was injured, and cooperated with us at the hospital.\""), .cross("Did the defendant try to brake?", "\"There are no brake marks. That could mean no braking, or a late reaction.\""), .cross("Was the defendant wearing a seat belt?", "\"Yes. {D.He} was belted and conscious when I arrived.\"")],
        defenseRole: "Restaurant server",
        defenseExam: [.direct("What do you do?", "\"I am a server at a restaurant. I wait tables during the lunch and early afternoon shifts.\""), .direct("What did {D} drink?", "\"Two beers over a long lunch. I remember because {D} ordered slowly and ate a full meal.\""), .direct("How long did the defendant stay?", "\"About two hours. {D.He} sat in my section, and we chatted between orders.\""), .direct("When did the defendant leave?", "\"Maybe three. I did not note it exactly, but it was in the middle of the afternoon.\""), .direct("How did the defendant seem when leaving?", "\"Fine. {D.He} walked steadily, paid the bill, and tipped well. I would not have thought twice.\""), .direct("Did you serve anyone else at the defendant's table?", "\"No. {D.He} was alone, and I served each round myself.\""), .cross("Do you keep count of every drink for every table?", "\"Not exactly. I recall two beers, but a busy lunch can blur things.\""), .cross("Could {D} have ordered at the bar?", "\"I suppose so. I only served the table, and I cannot say what happened at the bar.\""), .cross("Did you see the defendant after you left the restaurant?", "\"No. My shift ended soon after, and I did not see where {D.he} went.\""), .cross("Would two beers raise a level to .12 two hours after a crash?", "\"I do not know. I am a server, not a scientist.\""), .cross("Do you know how the defendant spent the hours after three?", "\"No. I know only what I saw at the restaurant.\"")],
        theory: ("{D} drove impaired across the line and killed a child.", "A deer in the road and old drinks."),
        allocution: "\"There's nothing I can say that will fix this. I'm sorry.\"",
        truths: ("{DL} had been drinking at a friend's house until dusk, long after the restaurant.", "The deer was hit by a car ahead of the pickup and was still in the road."),
        defendant: [.direct("Had you been drinking?", "\"Two beers at lunch. I stopped there, ate a full meal, and I did not feel impaired when I left.\""), .direct("What did you see on the road?", "\"A deer jumped out at dusk, and I swerved. I felt the truck leave my lane, and then the van was in front of me.\""), .direct("Why does the blood show .12?", "\"I do not know how. I only had two beers, hours before, and I cannot explain the number.\""), .direct("Did you see the van?", "\"Too late. I saw it as I came back from the swerve, and there was no time to do anything.\""), .direct("What did you do after the crash?", "\"I got out, ran to the van, and tried to help. I was crying, and I stayed until the ambulances came.\""), .direct("What do you want the family to know?", "\"I am so sorry. I would give anything to change that day, and I think about {V} every hour.\""), .cross("You crossed the center line, didn't you?", "\"Yes. I swerved for the deer and could not correct. I wish I had not.\""), .cross("You never braked, did you?", "\"I do not remember braking. It all happened in a second.\""), .cross("Your blood was .12 two hours later, wasn't it?", "\"That is what the test says. I do not understand it, and I do not dispute that it is what the test says.\""), .cross("A child died because your truck crossed the line, didn't a child?", "\"Yes. I will carry that forever.\""), .cross("You had been drinking, hadn't you?", "\"Two beers at lunch. I know that is not nothing.\"")],
        openings: ("At dusk on a two-lane road, a pickup driven by {D} crossed the center line and hit a family van head-on, killing {V}, a seven-year-old in the back seat. A hospital draw two hours later measured .12, and tire marks show no braking.", "A deer ran into the road, and {D} swerved. Two beers at lunch, hours earlier, and a split second on a dusk road do not make a reckless killer."),
        closings: ("Across the center line, no braking, a .12 two hours later that would have been higher at the crash. A child is dead because {D} chose to drive.", "A deer in the road, two beers hours earlier, and a swerve that came too late. The State must prove {D} was impaired at the crash, and not just that a tragedy happened."),
        timeline: [(0, "2 p.m.: lunch and two beers."), (0, "Afternoon: more drinks, the State says."), (0, "7:40 p.m.: the crash."), (0, "9:40 p.m.: the blood draw.")],
        identified: "A trooper and a blood draw.",
        aggravating: ["The victim was very young"],
        mood: .wantsConviction,
        doctrines: ["intoxication"],
        genders: ["V": .male])

    static let cocaineBagStopV1 = SmallCases.make(
        key: "story.cocaineBagStop",
        category: .drugs,
        headlines: ["Traffic Stop at Motel Exit Turns Up Packaged Cocaine", "Deputy Finds Pager Money and Baggies in Door Panel"],
        law: "pwisd",
        threshold: 7,
        spec: "Possessed with intent to sell or deliver cocaine, a Schedule II controlled substance, on {DATE}.",
        ages: 21...50,
        victim: false,
        summary: "A deputy stopped {D} for an expired tag on {DATE} as {D.he} left a motel lot. A drug dog alerted, and in the driver's door panel were eleven twisted baggies of powder, a roll of $1 bags, and $640. The lab found cocaine in all eleven, about 7 grams. {DL} says a friend borrowed the car the day before and the cash was from a yard sale.",
        state: [E(.physical, 3, "Door Panel Bags", "Eleven twisted baggies with cocaine, about 7 grams total, inside the driver's door.", .search), E(.physical, 2, "Bags and Cash", "A roll of small zip bags and $640 in small bills."), E(.forensic, 2, "Lab Report", "Cocaine in each of the eleven baggies.")],
        defense: [E(.statement, 2, "Borrowed Car", "{D} says a friend borrowed the car the day before."), E(.document, 1, "Yard Sale", "A listing for a yard sale the weekend before.")],
        role: "Sheriff's deputy",
        exam: [.direct("Why did you stop {D}?", "\"For an expired tag as {D} left a motel lot. It was a routine traffic stop, nothing more at that point.\""), .direct("What did the dog do?", "\"Sat and alerted at the driver's door. That is how this dog signals an odor of narcotics.\""), .direct("What did you find in the door?", "\"Eleven twisted baggies of powder inside the driver's door panel, along with a roll of small zip bags and $640 in small bills.\""), .direct("What did the lab report?", "\"Cocaine in all eleven baggies, about 7 grams in total. That matches the weight of a small supply for sale.\""), .direct("Where was the cash?", "\"In the car, in small bills. $640 together with the zip bags suggested packaging and sales.\""), .direct("What did the defendant say?", "\"That the car had been borrowed by a friend the day before and that the cash came from a yard sale.\""), .cross("Whose prints were on the bags?", "\"None usable. The baggies were twisted plastic, and we did not get a clear print.\""), .cross("Did anyone see the defendant sell anything?", "\"No. We did not see a sale, and we had no informant who named {D.him}.\""), .cross("Did the defendant consent to the search?", "\"The dog's alert gave us probable cause. {D.He} did not resist and was cooperative.\""), .cross("Did you check who borrowed the car?", "\"{DL} named a friend, and we spoke to the friend. I will not go further.\""), .cross("Was the defendant nervous at the stop?", "\"Somewhat. Most people are when a dog walks around the car.\"")],
        defenseRole: "Friend of {DL}",
        defenseExam: [.direct("How do you know {D}?", "\"We are friends. I have known {D} for years, and we help each other out with rides and favors.\""), .direct("Did you borrow the car?", "\"Yes, the day before the stop. I needed to run errands, and {D.he} said I could use it.\""), .direct("How long did you have it?", "\"Most of the day. I returned it that evening to the motel where {D.he} was staying.\""), .direct("Did you leave anything in it?", "\"Not that I know. I did not open the door panel, and I did not put anything in the car.\""), .direct("Did you see anything in the door panel?", "\"No. I did not look there, and I did not use the driver's door much.\""), .direct("What did you use the car for?", "\"Groceries, a doctor's visit, and a quick trip to a friend's place. Nothing out of the ordinary.\""), .cross("Did you drive alone?", "\"Most of the time, yes. Once I had a passenger, a friend who rode along.\""), .cross("Did you ever use drugs?", "\"I am not going to discuss that. I did not put any baggies in the car.\""), .cross("Did you tell the defendant how you used the car?", "\"Not in detail. I said it was errands, and {D.he} did not ask.\""), .cross("Did the defendant know you were at the motel?", "\"{D.He} was staying at the motel then, so yes, I returned the car there.\""), .cross("Are you protecting the defendant?", "\"I am telling the truth. I would not lie for anyone.\"")],
        theory: ("{D} had packaged cocaine hidden in the car.", "A borrowed car and a yard sale."),
        allocution: "\"I should have checked the car. I'm sorry.\"",
        truths: ("{DL}'s phone has a note listing weights and prices.", "The friend later pleaded guilty to selling cocaine from the same motel."),
        defendant: [.direct("Were those drugs yours?", "\"No. I did not own cocaine, I did not put it in the door, and I did not know it was there.\""), .direct("Who had the car?", "\"A friend, the day before. The friend borrowed it for errands and returned it that evening.\""), .direct("Where did the cash come from?", "\"A yard sale. I sold furniture and tools, and I kept the money in the car for the motel bill.\""), .direct("Why were you at the motel?", "\"A friend was staying there. I was helping with rides and a few errands.\""), .direct("Why did you have a roll of small zip bags?", "\"For my yard sale. I used them to package small items like screws, washers, and jewelry.\""), .direct("What do you want the jury to know?", "\"I never sold drugs. I lent a car to a friend and did not check it afterward.\""), .cross("The baggies were in your driver's door panel, weren't they?", "\"Yes, in my car. I did not put them there.\""), .cross("You had a roll of small zip bags and $640 in small bills, didn't you?", "\"Yes. They were from the yard sale, and I can show you what I sold.\""), .cross("Eleven baggies of cocaine, and you knew nothing?", "\"Nothing. I did not look in the door panel in months.\""), .cross("You cannot produce a record of the yard sale, can you?", "\"A few pictures and a friend who bought a table. I did not keep a ledger.\""), .cross("You were leaving a motel known for drug sales, weren't you?", "\"I was leaving a motel where a friend was staying. I did not know its reputation.\"")],
        openings: ("A deputy stopped {D} for an expired tag as {D} left a motel lot. A drug dog alerted, and in the driver's door panel were eleven twisted baggies holding about 7 grams of cocaine, a roll of small zip bags, and $640.", "A friend borrowed the car the day before, and the cash came from a yard sale. No one saw {D} sell anything, and there are no usable prints on a single baggie."),
        closings: ("Eleven baggies in {D}'s door panel, small bills, a roll of zip bags, and a motel lot. The setup tells you what the baggies were for.", "A friend who borrowed the car, no prints, and no sale seen by anyone. The State has drugs in a car and not drugs in {D}'s hands."),
        timeline: [(-1, "A friend borrows the car, {DL} says."), (0, "Morning: {DL} leaves the motel."), (0, "10:05 a.m.: the stop."), (0, "10:30 a.m.: the dog alerts.")],
        identified: "A traffic stop and a drug dog.",
        aggravating: ["The offense was committed for pecuniary gain"],
        mood: .indifferent,
        doctrines: ["searchSeizure", "burdenOfProof"],
        genders: ["D": .male])

    static let sweepstakesParlorV1 = SmallCases.make(
        key: "story.sweepstakesParlor",
        category: .robbery,
        headlines: ["Attendant Robbed at Gunpoint at Closing Time in Game Room", "Toy Pistol Found in Suspect's Truck, Defense Says"],
        law: "dangerousRobbery",
        threshold: 7,
        spec: "Took $2,100 in cash from the person and presence of {V}, an employee of a game room, by the use and threatened use of a dangerous weapon, a black pistol, whereby {V}'s life was endangered and threatened, on {DATE}.",
        ages: 19...40,
        victim: true,
        summary: "Just before 11 p.m. on {DATE}, a masked man held a black pistol on {V}, an attendant locking up a game room, and made {V} empty the safe bag. He took $2,100. A truck leaving the lot was traced to {D}. Deputies found $1,950 in a tackle box and a plastic airsoft pistol under the seat. {DL} says the pistol would not stand up as a dangerous weapon, and that a cousin had the truck that night.",
        state: [E(.video, 3, "Lot Camera", "A masked man forces {V} back inside, then leaves in a dark truck at 10:52 p.m."), E(.physical, 3, "Cash and Pistol", "$1,950 in a tackle box in the truck bed and a black airsoft pistol, magazine empty.", .search), E(.document, 2, "Plate Match", "A neighbor's doorbell camera catches the truck's tag, registered to {D}.")],
        defense: [E(.document, 2, "Airsoft Specs", "The pistol fires plastic pellets from a spring and was empty when seized."), E(.statement, 1, "Cousin", "{DL} says a cousin borrowed the truck that night.")],
        role: "Game room attendant",
        exam: [.direct("What happened that night?", "\"A masked person pointed a black pistol at me and said to fill the bag. I was locking up the game room, just before 11.\""), .direct("How afraid were you?", "\"I thought it was real. I could not breathe, and my hands shook as I emptied the safe bag.\""), .direct("What was taken?", "\"$2,100 in cash. I handed it over because I was sure I would be shot otherwise.\""), .direct("Did you see the face?", "\"No. A mask covered everything. I saw only eyes and a dark jacket.\""), .direct("What did you see of the vehicle?", "\"A dark truck leaving the lot at about 10:52. I did not see the plate, and I could not tell the make.\""), .direct("Did you know the pistol was plastic?", "\"Not then. I learned afterward that it was an airsoft replica, and it still looked real to me.\""), .cross("Was there an orange tip on the barrel?", "\"No. There was no orange tip that I could see, and I cannot say if one had been removed.\""), .cross("Did the person speak?", "\"A few words. I could not recognize a voice and I would not guess about the person.\""), .cross("How tall was the person?", "\"Medium height. I cannot say more, and I would not swear it was {D}.\""), .cross("Did the person threaten to shoot?", "\"Not in words. The pistol was pointed, and the message was clear.\""), .cross("Were you hurt?", "\"No. I was shaken but physically fine.\"")],
        defenseRole: "Firearms examiner retained by the defense",
        defenseExam: [.direct("What do you do for a living?", "\"I am a firearms examiner. I examine weapons and replicas, and I was retained by the defense in this case.\""), .direct("What is the pistol found in the truck?", "\"A spring airsoft replica with a plastic barrel. It fires small plastic pellets with a spring, not with gunpowder.\""), .direct("Does it look real from across a counter?", "\"With the orange tip removed, yes. It is a very realistic copy, and many people cannot tell the difference at a distance.\""), .direct("Could it cause serious injury?", "\"Rarely. A spring airsoft pellet can sting and cause a bruise, but it is not likely to cause serious harm.\""), .direct("Was the magazine empty?", "\"Yes. The magazine was empty, and there were no pellets in the chamber.\""), .direct("Is it a dangerous weapon under the law?", "\"In my opinion, a plastic spring replica is not a dangerous weapon in the sense a real firearm is.\""), .cross("Could a victim reasonably believe it was real?", "\"Yes. I said it looks real, and a victim could easily believe it.\""), .cross("Could it be used to frighten someone into giving up money?", "\"Yes. That is what a realistic replica can do.\""), .cross("Are you paid for your opinion?", "\"Yes. I am paid for my time. My opinion would be the same if I were not.\""), .cross("Did you examine the pistol in this case?", "\"Yes. I examined it and tested it, and my findings are as I described.\""), .cross("Did you determine who owned it?", "\"No. That was not part of my work.\"")],
        theory: ("{D} robbed a clerk at gunpoint at closing.", "A plastic toy, a mask, and a cousin with the keys."),
        allocution: "\"I'm sorry. I put {V} through something terrible.\"",
        truths: ("{DL} texted a friend, \"Need rent by Friday. I know a place,\" two days before.", "The cousin was seen wearing the same ski mask the week after."),
        defendant: [.direct("Were you there?", "\"No. I was not at that game room, and I did not rob anyone.\""), .direct("Whose pistol was it?", "\"A toy a relative's child left in my truck. I never looked at it closely, and I did not use it for anything.\""), .direct("Where did the $1,950 come from?", "\"Savings. I keep cash in a tackle box in the truck bed. I had been saving for a long time.\""), .direct("Where was the truck that night?", "\"With my cousin. I lent it for the evening, and I was at home.\""), .direct("How did you feel when deputies stopped you?", "\"Confused. I told them everything I knew, including who had the truck.\""), .direct("What do you want the jury to know?", "\"I did not rob anyone. I lent my truck to a relative, and I am sorry for what {V} went through.\""), .cross("The truck on camera is registered to you, isn't it?", "\"Yes, it is my truck. My cousin had it that night.\""), .cross("$1,950 in a tackle box, and $2,100 was taken, wasn't it?", "\"That is a coincidence. It was my savings, and I did not know how much was taken.\""), .cross("The pistol was under your seat, wasn't it?", "\"It was in the truck. I did not put it there, and I did not know.\""), .cross("You cannot prove your cousin had the truck, can you?", "\"My cousin knows. I hope the cousin will tell the truth.\""), .cross("You have no receipt for those savings, do you?", "\"No. I keep cash. I know that is hard to prove.\"")],
        openings: ("Just before 11 p.m., a masked person held a black pistol on {V}, an attendant locking up a game room, and made {V} empty the safe bag of $2,100. A truck leaving the lot was traced to {D}, and deputies found $1,950 in a tackle box and an airsoft pistol under the seat.", "{D}'s truck was lent to a cousin that night, and {D} was at home. The pistol is a plastic toy, and cash in a tackle box is savings."),
        closings: ("A masked robbery, a truck registered to {D}, nearly all the cash in a tackle box, and a pistol under the seat. {V} thought the pistol was real, and that is what matters.", "A cousin with the keys, savings in a tackle box, and a toy pistol no one can tie to {D}. The State cannot show who wore that mask."),
        timeline: [(0, "10:45 p.m.: {V} locks up the game room."), (0, "10:50 p.m.: the robbery."), (0, "10:52 p.m.: the truck leaves."), (1, "Deputies find the tackle box.")],
        identified: "A lot camera and a plate.",
        aggravating: ["The offense involved a threat"],
        mood: .wantsConviction,
        impact: "I jump when the door opens now.",
        doctrines: ["lesserIncluded", "burdenOfProof", "eyewitnessID"],
        genders: ["D": .male])

